    _ESTADOS_EM_MEMORIA[conversation_id] = estado

    gerar_paineis(trilha_dir, painel_dir, repositorio_contato=repositorio_contato)

    return _json("200 OK", _turno_para_json(turno, repositorio_trilha, conversation_id))


