function erro(msg) { ajuda.textContent = msg; ajuda.className = "ajuda erro"; }

function progresso(n) {
  $("passo-txt").textContent = n > 9 ? "Tudo pronto" : `Pergunta ${n} de 9`;
  $("barra").style.width = Math.min(n - 1, 9) / 9 * 100 + "%";
}

// ── contato: salvo assim que nome+WhatsApp existem, atualizado quando o e-mail chega — nunca
// espera o fim do fluxo (o corretor pode precisar do contato mesmo se o lead abandonar antes do
// preço). Nome/WhatsApp/e-mail NUNCA entram no payload de /api/chat/cotar (ver cotar(), abaixo).
async function salvarContato() {
  if (!dados.nome || !dados.whatsappExibicao) return;
  try {
    await fetch("/api/chat/contato", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        conversation_id: conversationId,
        nome: dados.nome,
        whatsapp: dados.whatsappExibicao,
        email: dados.email || null,
      }),
    });
  } catch (e) {
    // Falha ao salvar contato não pode travar a cotação em andamento — o corretor perde o
    // registro deste lead, mas o lead continua a conversa (e o texto de preço, quando existir,
    // segue vindo só da /quote via /api/chat/cotar).
  }
}

// ── os passos, um por vez, na ordem da issue #46 (B.3) ──────────────────────────
const PASSOS = {
  nome() {
    progresso(1);
    mensagemBot("Para começar, <b>qual é o seu nome completo?</b>");
    mostrarDoca({ placeholder: "Nome completo", dica: "Usamos seu nome para o corretor falar com você." });
    passoAtual = (v) => {
      const nome = v.trim();
      const partesValidas = nome.split(/\s+/).filter((p) => (p.match(/[A-Za-zÀ-ÿ]/g) || []).length >= 2);
      if (partesValidas.length < 2) return erro("Digite nome e sobrenome.");
      mensagemLead(nome); dados.nome = nome; seguir("whatsapp");
    };
  },
  whatsapp() {
    progresso(2);
    mensagemBot("Qual o seu <b>WhatsApp</b>? Escolha o país e digite o número.");
    mostrarDoca({ placeholder: "Número, com DDD", pais: true });
    paisSel.innerHTML = "";
    paises.forEach((p) => {
      const o = document.createElement("option");
      o.value = p.iso; o.textContent = `${p.bandeira} ${p.nome} +${p.ddi}`;
      if (p.iso === "BR") o.selected = true;
      paisSel.append(o);
    });
    const paisAtual = () => paises.find((p) => p.iso === paisSel.value) || paises[0];
    const aplicarMascaraBR = () => {
      const d = entrada.value.replace(/\D/g, "").slice(0, 11);
      if (d.length > 6) entrada.value = `(${d.slice(0, 2)}) ${d.slice(2, d.length > 10 ? 7 : 6)}-${d.slice(d.length > 10 ? 7 : 6)}`;
      else if (d.length > 2) entrada.value = `(${d.slice(0, 2)}) ${d.slice(2)}`;
      else entrada.value = d;
    };
    const aplicarMascaraOutro = () => { entrada.value = entrada.value.replace(/\D/g, "").slice(0, 14); };
    const atualizarTextos = () => {
      const p = paisAtual();
      // Textos EXATOS da issue #46: Brasil "Número, com DDD"; outros "Número de telefone, sem o
      // código do país" — nunca redigitados fora deste ponto único.
      if (p.iso === "BR") { entrada.placeholder = "Número, com DDD"; ajuda.textContent = "Ex.: (11) [REDIGIDO]8"; }
      else { entrada.placeholder = "Número de telefone, sem o código do país"; ajuda.textContent = `Só os números. O código +${p.ddi} já está no país escolhido.`; }
    };
    paisSel.onchange = () => { entrada.value = ""; entrada.oninput = paisSel.value === "BR" ? aplicarMascaraBR : aplicarMascaraOutro; atualizarTextos(); };
    entrada.oninput = aplicarMascaraBR;
    atualizarTextos();
    passoAtual = (v) => {
      const p = paisAtual();
      const digitos = v.replace(/\D/g, "");
      let exibicao;
      if (p.iso === "BR") {
        if (digitos.length !== 10 && digitos.length !== 11) return erro("Digite DDD e número, ex.: (11) [REDIGIDO]8.");
        const ddd = digitos.slice(0, 2), resto = digitos.slice(2);
        exibicao = `+${p.ddi} (${ddd}) ${digitos.length === 11 ? resto.slice(0, 5) + "-" + resto.slice(5) : resto.slice(0, 4) + "-" + resto.slice(4)}`;
      } else {
        if (digitos.length < 4 || digitos.length > 14) return erro("Digite só os números do telefone, sem o código do país.");
        exibicao = `+${p.ddi} ${digitos}`;
      }
      mensagemLead(exibicao);
      dados.whatsappExibicao = exibicao;
      salvarContato();
      seguir("email");
    };
  },
  email() {
    progresso(3);
    mensagemBot("Se quiser, deixe seu <b>e-mail</b>. É opcional.");
    mostrarDoca({
      placeholder: "[REDIGIDO]", tipo: "email",
      botoes: [{ rotulo: "Pular", acao: () => { mensagemLead("Prefiro não informar"); dados.email = null; salvarContato(); seguir("idade"); } }],
    });
    passoAtual = (v) => {
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) return erro("Esse e-mail não parece válido. Confira ou toque em Pular.");
      mensagemLead(v.trim()); dados.email = v.trim(); salvarContato(); seguir("idade");
    };
  },
  idade() {
    progresso(4);
    mensagemBot("E <b>quantos anos você tem?</b>");
    mostrarDoca({ placeholder: "Sua idade, ex.: 35", tipo: "number", dica: "Usamos a idade para a faixa de preço." });
    passoAtual = (v) => {
      const n = parseInt(v, 10);
      if (!Number.isInteger(n) || n <= 0) return erro("Digite só o número, ex.: 35.");
      mensagemLead(`${n} anos`); dados.idade = n;
      // Menor de 18: mensagem exata da issue #46, sem tentativa de cotação — decisão de
      // política que é só do frontend guiado (nunca chega a chamar /api/chat/cotar).
      if (n < 18) return menorDeIdade();
      seguir("modelo");
    };
  },
  modelo() {
    progresso(5);
    mensagemBot("Qual o <b>modelo</b> do seu carro? (ex.: Onix, HB20, Corolla)");
    mostrarDoca({ placeholder: "Modelo do carro", dica: "O modelo fica registrado para o corretor; nesta cotação não altera o preço." });
    passoAtual = (v) => {
      const modelo = v.trim();
      if (modelo.length < 2) return erro("Digite o modelo do carro.");
      mensagemLead(modelo); dados.veiculo_modelo = modelo; seguir("ano");
    };
  },
  ano() {
    progresso(6);
    const anoAtual = new Date().getFullYear();
    mensagemBot(`E o seu ${esc(dados.veiculo_modelo)}, <b>de que ano é?</b>`);
    const anos = [0, 1, 2, 3, 4].map((i) => anoAtual - i);
    mostrarDoca({
      placeholder: "Ou digite o ano, ex.: 2019", tipo: "number",
      botoes: anos.map((a) => ({ rotulo: String(a), acao: () => passoAtual(String(a)) })),
      dica: "Carros com até 20 anos de uso são aceitos.",
