  async plano() {
    progresso(8);
    // Coberturas e franquia vêm SEMPRE de GET /api/planos (proxy de infra.planos_http) — nunca
    // escritas à mão aqui (issue #46, B.3.8).
    const resposta = await fetch("/api/planos");
    if (!resposta.ok) {
      mensagemBot("Não consegui carregar os planos agora. Toque para tentar de novo.", { cls: "sistema" });
      mostrarDoca({ textoLivre: false, botoes: [{ rotulo: "Tentar de novo", primaria: true, acao: () => PASSOS.plano() }] });
      return;
    }
    const catalogo = await resposta.json();
    const planos = catalogo.planos || [];
    const moeda = catalogo.moeda || "BRL";
    mensagemBot(
      'Agora escolha o <b>plano</b>. Toque no card que faz mais sentido para você:' +
      '<details><summary>O que é franquia?</summary>Franquia é o valor que você paga do seu bolso ' +
      'quando usa o seguro para consertar o carro depois de um dano parcial, como uma batida. O ' +
      'seguro paga o restante do conserto. Exemplo ilustrativo: com franquia de R$ 3.000,00, um ' +
      'conserto de R$ 8.000,00 fica R$ 3.000,00 para você e R$ 5.000,00 para o seguro. Quanto ' +
      'menor a franquia, menos você paga quando precisa usar o seguro.</details>'
    );
    const grade = el("div", "planos");
    planos.forEach((p) => {
      const franquia = Number(p.franquia || 0).toLocaleString("pt-BR", { style: "currency", currency: moeda });
      const coberturas = (p.coberturas || []).map((c) => `<li>${esc(c)}</li>`).join("");
      const card = el("button", "plano");
      card.type = "button"; card.setAttribute("aria-pressed", "false");
      card.innerHTML = `<h4>${esc(p.nome || p.id)}</h4><div class="franquia">Franquia <b>${franquia}</b></div><ul>${coberturas}</ul>`;
      card.onclick = () => {
        grade.querySelectorAll(".plano").forEach((c) => { c.setAttribute("aria-pressed", "false"); c.disabled = true; });
        card.setAttribute("aria-pressed", "true");
        mensagemLead(`Plano ${p.nome || p.id}`);
        dados.plano_id = p.id; dados.planoNome = p.nome || p.id;
        seguir("inicio");
      };
      grade.append(card);
    });
    anexar(grade);
    mostrarDoca({ textoLivre: false, dica: "O preço de cada plano depende do seu perfil. Ele aparece depois do resumo." });
  },
  inicio() {
    progresso(9);
    mensagemBot("Por último: <b>quando o seguro deve começar?</b>");
    const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
    const proximoMes = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 1);
    const dataBR = (d) => d.toLocaleDateString("pt-BR");
    mostrarDoca({
      tipo: "date",
      botoes: [
        { rotulo: `Hoje (${dataBR(hoje)})`, acao: () => escolherInicio(hoje) },
        { rotulo: `1º do próximo mês (${dataBR(proximoMes)})`, acao: () => escolherInicio(proximoMes) },
      ],
      dica: "Ou escolha outra data no campo acima.",
    });
    entrada.min = hoje.toISOString().slice(0, 10);
    passoAtual = (v) => {
      if (!v) return erro("Escolha uma data.");
      const [a, m, d] = v.split("-").map(Number);
      escolherInicio(new Date(a, m - 1, d));
    };
  },
  resumo() {
    progresso(10);
    mensagemBot("Confere se está tudo certo:");
    // `new Date("2026-09-13")` (string SEM hora) é interpretado como meia-noite UTC — num
    // fuso atrás de UTC (Brasil, UTC-3) isso vira "12/09/2026" na tela, um dia a menos do que
    // foi escolhido (achado ao vivo no Browser desta sessão, PR 2 issue #46). Construindo a
    // partir dos componentes ano/mês/dia (fuso LOCAL, igual ao construtor já usado em
    // escolherInicio/passoAtual do CEP) evita o parse como UTC.
    const dataBR = (iso) => { const [a, m, d] = iso.split("-").map(Number); return new Date(a, m - 1, d).toLocaleDateString("pt-BR"); };
    const linha = (rot, val, passo) => `<dt>${esc(rot)}</dt><dd>${esc(val)}</dd><dd><button class="alt" type="button" data-passo="${passo}">alterar</button></dd>`;
    const c = el("div", "cartao-resumo");
    c.innerHTML = `<dl>
      ${linha("Nome", dados.nome, "nome")}
      ${linha("WhatsApp", dados.whatsappExibicao, "whatsapp")}
      ${linha("E-mail", dados.email || "não informado", "email")}
      ${linha("Idade", dados.idade + " anos", "idade")}
      ${linha("Carro", dados.veiculo_modelo + " " + dados.veiculo_ano, "modelo")}
      ${linha("CEP", dados.cep || "não informado", "cep")}
      ${linha("Plano", dados.planoNome, "plano")}
      ${linha("Início", dataBR(dados.data_inicio), "inicio")}
    </dl>`;
    c.querySelectorAll(".alt").forEach((b) => b.onclick = () => {
      voltarAoResumo = true;
      mensagemLead("Quero alterar: " + b.previousElementSibling.textContent);
      PASSOS[b.dataset.passo]();
    });
    anexar(c);
    mostrarDoca({ textoLivre: false, botoes: [{ rotulo: "Cotar agora →", primaria: true, acao: cotar }] });
  },
};

