<script>
(function () {
  "use strict";

  // ── identidade da conversa ([REDIGIDO]: o estado entre turnos vive no servidor, por
  // conversation_id, dentro de um dict em memória do processo — perdido ao reiniciar). O cliente só
  // precisa gerar um id estável para esta aba e reenviá-lo em toda chamada de /api/chat/*.
  const conversationId = "chat-" + (
    window.crypto && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(16) + Math.random().toString(16).slice(2)
  );

  const $ = (id) => document.getElementById(id);
  const hero = $("hero"), conversa = $("conversa"), fio = $("fio"), doca = $("doca");
  const rapidas = $("rapidas"), form = $("form"), entrada = $("entrada"), ajuda = $("ajuda"), paisSel = $("pais");

  let dados = {};        // o que o lead já respondeu, nesta aba
  let passoAtual = null;  // validador/handler da pergunta em tela
  let voltarAoResumo = false; // "alterar" no resumo: responde só o campo escolhido e volta pro resumo
  let paises = [{ iso: "BR", nome: "Brasil", ddi: 55, bandeira: "🇧🇷" }]; // fallback até o fetch chegar

  function el(tag, cls, html) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html != null) e.innerHTML = html;
    return e;
  }

